import {captainLevel} from './showtime-rules.js';
import {LEVELS,newLeaguePolicy,trainLeagueBatch,randomGenerator,leagueEvaluation} from './league.js';
self.onmessage=({data})=>{const base=LEVELS.find(l=>l.id===data.levelId),level=base?captainLevel(base,data.captainRule||'native'):null;if(!level){self.postMessage({type:'error',message:'Unknown arena'});return;}const {weights,seed=42,total=10000}=data,q=newLeaguePolicy(level),random=randomGenerator(seed),history=[];for(let start=0;start<total;start+=250){trainLeagueBatch(q,weights,level,start,Math.min(250,total-start),total,random);if(start%1000===0||start+250>=total){const metrics=leagueEvaluation(q,weights,level);history.push({episode:start+250,...metrics});self.postMessage({type:'progress',episode:start+250,total,metrics});}}self.postMessage({type:'complete',q,weights,levelId:level.id,seed,total,history,metrics:leagueEvaluation(q,weights,level)});};
